WITH metrics AS (SELECT id, device_code, temp_c, humidity, pressure, status_bits, firmware, MIN(humidity) OVER w_ordered AS last4_min_humidity, AVG(humidity) OVER w_ordered AS last4_avg_humidity, SUM(humidity) OVER w_ordered AS last4_sum_humidity FROM device_readings WINDOW w_ordered AS (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT id, device_code, humidity, status_bits, last4_min_humidity, last4_avg_humidity, last4_sum_humidity, CASE WHEN device_code RLIKE '^(DV-03|DV-01)$' THEN 'GROUP_B' WHEN device_code RLIKE '^(DV-02|DV-04)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS device_code_zone FROM metrics;
